  headlineMesh.name = 'headline-text';
  headlineMesh.position.set(0, -1.75, 0.05);
  group.add(headlineMesh);

  const captionMesh = createMSDFText(
    captionItem.content || 'SAPPHIRE OVER DIAL / ZERO DISTORTION',
    {
      fontAtlas: ctx.fontAtlas,
      family: captionTypo.family,
      weight: captionTypo.fontWeight,
      fontSize: 0.09,
      letterSpacing: captionTypo.letterSpacing,
      lineHeight: captionTypo.lineHeight,
      color: paperColor,
      align: 'center',
      anchor: 'center',
    }
  );
  captionMesh.name = 'caption-text';
  captionMesh.position.set(0, -2.25, 0.05);
  group.add(captionMesh);

  // ================= CINEMATIC PRIMITIVES =================
  group.userData.handlers = {};

  const primitiveDisposers = [];
  const cinematicPrimitives = Array.isArray(cfg.cinematicPrimitives) ? cfg.cinematicPrimitives : [];
  cinematicPrimitives.forEach((primitive) => {
    const applyPrimitive = ctx.primitives && ctx.primitives[primitive.name];
    if (typeof applyPrimitive === 'function') {
      const disposer = applyPrimitive(group, primitive.params || {});
      if (typeof disposer === 'function') primitiveDisposers.push(disposer);
    }
  });

  // ================= CLEANUP =================
  group.userData.cleanup = () => {
    primitiveDisposers.forEach((dispose) => {
      try {
        dispose();
      } catch (e) {
        /* noop */
      }
    });

    gsap.killTweensOf(group);
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.rotation);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(causticMesh.scale);
    gsap.killTweensOf(prismMesh.rotation);

    causticMesh.onBeforeRender = null;

    prismGeometry.dispose();
    prismMaterial.dispose();
    coreGeometry.dispose();
    coreMaterial.dispose();
    causticGeometry.dispose();
    causticMaterial.dispose();

    [headlineMesh, captionMesh].forEach((textObj) => {
      textObj.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
      if (typeof textObj.userData?.dispose === 'function') {
        textObj.userData.dispose();
      }
    });

    if (typeof rimLight.dispose === 'function') rimLight.dispose();

    group.userData.handlers = {};
  };

  return group;
}
